using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class AndroidStrategyDraftCardFileStoreTests{[Fact]public void Card_round_trips_without_live_authority(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var path=Path.Combine(root,"card.json");var card=new AndroidStrategyDraftCard("D","s",2,true,Array.Empty<string>(),false);var store=new AndroidStrategyDraftCardFileStore(path);store.Save(card);Assert.Equal(card,store.Load());}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}}
